solution:
interface CounterState {
  count: number;
  inc: () => void;
  reset: () => void;
}

function createCounterStore(set: (updater: any) => void): CounterState {
  return {
    count: 0,
    inc: () => set((state: CounterState) => ({ count: state.count + 1 })),
    reset: () => set({ count: 0 }),
  };
}
